        return std::nullopt;

    if (auto* ref = sc<PHLWORKSPACEREF*>(luaL_testudata(L, idx, LUA_WORKSPACE_MT)); ref) {
        const auto ws = ref->lock();
        if (!ws) {
            Internal::configError(L, "{}: workspace object is expired", fnName);
            return std::nullopt;
